/* Menu Hapvida (base-header-dropzone) — visibilidade com/sem barra flutuante */

@media screen and (min-width: 1400px) {
    .base-header-dropzone {
        top: 80px!important; /* 0 + 80 */
    }

    body.has-control-menu:not(.float-bar-closed)
      .hapvida-search-overlay {
            top: 44px;
    }

    body.has-control-menu .base-header-dropzone {
        top: 155px!important; /* 56 + 80 */
    }
    body.has-control-menu.has-edit-mode-menu .base-header-dropzone {
        top: 224px!important; /* 144 + 80 */
    }

    body.float-bar-closed .base-header-dropzone {
        top: 0px!important;
    }
    body.float-bar-closed.has-control-menu .base-header-dropzone {
        top: 56px!important;
    }
    body.float-bar-closed.has-control-menu.has-edit-mode-menu .base-header-dropzone {
        top: 144px!important;
    }
}

@media screen and (min-width: 981px) and (max-width: 1400px) {
    .base-header-dropzone {
        top: 115px!important; /* 0 + 80 */
    }

    body.has-control-menu .base-header-dropzone {
